CREATE DATABASE IF NOT EXISTS `SFweb` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `SFweb`;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `ai_diagnoses`;
CREATE TABLE `ai_diagnoses` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pond_id` int NOT NULL,
  `image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `annotated_image_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `disease_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `confidence` decimal(5,4) NOT NULL,
  `severity` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `status` enum('pending','confirmed','dismissed','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `model_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Atlas200I-FishDisease',
  `raw_result` longtext COLLATE utf8mb4_unicode_ci,
  `source` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'seed',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_ai_pond_time` (`pond_id`,`created_at`),
  CONSTRAINT `fk_ai_pond` FOREIGN KEY (`pond_id`) REFERENCES `ponds` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='AI鱼病识别记录表';

DROP TABLE IF EXISTS `alarms`;
CREATE TABLE `alarms` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `alarm_type` enum('water_quality','device','ai_disease','communication','system') COLLATE utf8mb4_unicode_ci NOT NULL,
  `pond_id` int DEFAULT NULL,
  `device_id` int DEFAULT NULL,
  `parameter_key` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `severity` enum('low','medium','high','critical') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'medium',
  `message` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('open','acknowledged','resolved') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `acknowledged_by` int DEFAULT NULL,
  `resolved_by` int DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_alarms_status_time` (`status`,`created_at`),
  KEY `idx_alarms_pond_time` (`pond_id`,`created_at`),
  KEY `fk_alarms_device` (`device_id`),
  KEY `fk_alarms_ack_user` (`acknowledged_by`),
  KEY `fk_alarms_resolve_user` (`resolved_by`),
  CONSTRAINT `fk_alarms_ack_user` FOREIGN KEY (`acknowledged_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_alarms_device` FOREIGN KEY (`device_id`) REFERENCES `devices` (`id`),
  CONSTRAINT `fk_alarms_pond` FOREIGN KEY (`pond_id`) REFERENCES `ponds` (`id`),
  CONSTRAINT `fk_alarms_resolve_user` FOREIGN KEY (`resolved_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='告警事件表';

DROP TABLE IF EXISTS `automation_rules`;
CREATE TABLE `automation_rules` (
  `id` int NOT NULL AUTO_INCREMENT,
  `rule_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pond_id` int DEFAULT NULL,
  `trigger_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
