) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自动控制规则表';

DROP TABLE IF EXISTS `device_commands`;
CREATE TABLE `device_commands` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `device_id` int NOT NULL,
  `command_type` enum('start','stop','toggle','feed','inspect','reset') COLLATE utf8mb4_unicode_ci NOT NULL,
